## Interactive multi-file web app recipe (D3 + HTTP)

When the task asks for a single-page web app with a specific file layout (e.g., `index.html` + `js/` + `css/` + `data/`), follow this recipe exactly.

### Canonical layout

```
output/
  index.html                 # entry; links ./css/style.css, ./js/d3.vX.min.js, ./js/visualization.js
  js/
    d3.v6.min.js             # pinned local copy — version must match the task (v6, v7, etc.)
    visualization.js         # your code
  css/
    style.css
  data/                      # COPY of every input CSV/JSON the app reads
    <inputs>...
```

- All `<script src=...>`, `<link href=...>`, and `d3.csv(...)` paths MUST be **relative** (`./js/...`, `./data/...`, or bare `js/...`) so the app works under any server root.
- **Do not inline the data to avoid HTTP.** The task's file layout implies the grader will serve the folder; `d3.csv` uses `fetch` which fails on `file://`, so a static server (the grader's) is expected.
- Pin D3 to the version the task specifies. Download once (e.g., `curl -o js/d3.v6.min.js https://d3js.org/d3.v6.min.js`); do not reference a CDN at runtime.

### Clustered force-directed bubble chart

```javascript
// Radius: AREA (not radius) proportional to size field; uniform fallback for missing values.
const UNIFORM_R = 20;
const rScale = d3.scaleSqrt()
    .domain([0, d3.max(data, d => d.marketCap || 0)])
    .range([14, 52]);
const radius = d => (d.marketCap ? rScale(d.marketCap) : UNIFORM_R);

// Deterministic per-sector cluster centers on a circle around chart center.
const sectors = Array.from(new Set(data.map(d => d.sector))).sort();
const cx = width / 2, cy = height / 2;
const R  = Math.min(width, height) * 0.24;
const centers = new Map(sectors.map((s, i) => {
    const a = (i / sectors.length) * 2 * Math.PI;
    return [s, { x: cx + R * Math.cos(a), y: cy + R * Math.sin(a) }];
}));

// Deterministic initial positions (no Math.random): seed from index.
data.forEach((d, i) => {
    const c = centers.get(d.sector);
    d.x = c.x + ((i * 37) % 11) - 5;
    d.y = c.y + ((i * 53) % 11) - 5;
});

const sim = d3.forceSimulation(data)
    .force('x', d3.forceX(d => centers.get(d.sector).x).strength(0.15))
    .force('y', d3.forceY(d => centers.get(d.sector).y).strength(0.15))
    .force('charge', d3.forceManyBody().strength(-10))
    .force('collide', d3.forceCollide(d => radius(d) + 2).iterations(3))
    .stop();
for (let i = 0; i < 300; i++) sim.tick();   // warm-up for deterministic layout
```

### Tooltip with conditional suppression (ETFs lack fields)

```javascript
bubbles.on('mouseover', (event, d) => {
    if (!d.marketCap || d.sector === 'ETF') return;   // suppress for incomplete rows
    tooltip.classed('visible', true)
        .html(`<strong>${d.ticker}</strong><br/>${d.name}<br/>${d.sector}`)
        .style('left', (event.pageX + 10) + 'px')
        .style('top',  (event.pageY - 10) + 'px');
});
```

### Bidirectional chart ↔ table linking (shared dispatcher)

```javascript
let selectedId = null;
function select(id) {
    selectedId = (selectedId === id) ? null : id;   // toggle
    highlightChart(selectedId);
    highlightTable(selectedId);
}
bubbles.on('click', (_, d) => select(d.ticker));
tableRows.on('click', d => select(d.ticker));

function highlightChart(id) {
    bubbles.classed('selected', d => d.ticker === id);
}
function highlightTable(id) {
    tableRows.classed('selected', d => d.ticker === id);
    if (id) {
        const row = document.querySelector(`tr[data-ticker="${id}"]`);
        if (row) row.scrollIntoView({ block: 'nearest' });
    }
}
```

CSS:
```css
circle.bubble.selected { stroke: #111; stroke-width: 3px; }
tr.selected            { background: #fff3a3; font-weight: 600; }
```

### Market-cap formatter

```javascript
function formatMarketCap(n) {
    if (n == null || isNaN(n)) return '—';
    const abs = Math.abs(n);
    if (abs >= 1e12) return (n / 1e12).toFixed(2) + 'T';
    if (abs >= 1e9)  return (n / 1e9 ).toFixed(2) + 'B';
    if (abs >= 1e6)  return (n / 1e6 ).toFixed(1) + 'M';
    if (abs >= 1e3)  return (n / 1e3 ).toFixed(1) + 'K';
    return String(n);
}
```

### Table sort (sector asc, then market cap desc, missing last)

```javascript
const sorted = data.slice().sort((a, b) => {
    if (a.sector !== b.sector) return d3.ascending(a.sector, b.sector);
    const am = a.marketCap, bm = b.marketCap;
    if (am == null && bm == null) return 0;
    if (am == null) return 1;         // missing last
    if (bm == null) return -1;
    return d3.descending(am, bm);
});
```
